import math

class Cerchio:
    def __init__(self, d):
        self.d = d
    def area(self):
        return math.pi * self.d**2 / 4
    def inerzia(self):
        return math.pi * self.d**4 / 64

class Tubo(Cerchio):
    def __init__(self, D, s):
        super().__init__(D)
        self.s = s

    def area(self):
        interno = Cerchio(self.d - 2 * self.s)
        return super().area() - interno.area()

    def inerzia(self):
        interno = Cerchio(self.d - 2 * self.s)
        return super().inerzia() - interno.inerzia()

t = Tubo(60, 5)
print(t.area(), t.inerzia())
